package io.knowledgebrain.learning;
import java.time.*;import java.util.*;import javax.sql.DataSource;
import org.flywaydb.core.Flyway;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;
class EvidenceSessionFixtures {
 final Clock clock=Clock.systemUTC();final UuidV7 ids=new UuidV7(clock);final String trace="d".repeat(32);
 DataSource ds;JdbcTemplate sql;RoadmapStore roadmaps;LearningStudyStore study;EvidenceSessionStore links;UUID space,actor,roadmap,node,otherNode;
 void init(){var source=new PGSimpleDataSource();source.setURL(System.getenv("BRAIN_TEST_LEARNING_DATABASE_URL"));source.setUser("brain_learning");source.setPassword(System.getenv("BRAIN_TEST_LEARNING_DATABASE_PASSWORD"));init(source);}
 void init(DataSource source){ds=source;Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();sql=new JdbcTemplate(ds);roadmaps=new RoadmapStore(ds,clock);study=new LearningStudyStore(ds,clock,roadmaps);links=new EvidenceSessionStore(ds,clock,roadmaps,study);space=ids.next();actor=ids.next();var root=roadmaps.create(space,actor,"Session links","",trace);roadmap=root.roadmapId();root=roadmaps.graph(space,roadmap,actor,1,new RoadmapGraph.Edit(List.of(new RoadmapGraph.NodeEdit("new:a","A",""),new RoadmapGraph.NodeEdit("new:b","B","")),List.of()),trace);node=root.nodes().stream().filter(n->n.title().equals("A")).findFirst().orElseThrow().nodeId();otherNode=root.nodes().stream().filter(n->n.title().equals("B")).findFirst().orElseThrow().nodeId();}
 String key(){return UUID.randomUUID().toString().replace("-","");}
 UUID evidence(String kind){UUID source=ids.next();return switch(kind){case "NOTE"->new LearningEvidenceStore(ds,clock,roadmaps).record(space,roadmap,actor,key(),new LearningEvidenceStore.Input(node,source,1,"Memo"),trace,()->new NoteReferenceClient.Reference(space,source,actor,1,"Pinned note","PRIVATE")).evidence().evidenceId();case "CONCEPT"->new ConceptEvidenceStore(ds,clock,roadmaps).record(space,roadmap,actor,key(),new ConceptEvidenceStore.Input(node,space,source,1,"Memo"),trace,()->new ConceptReferenceClient.Reference(space,source,space,actor,1,"Pinned concept","PRIVATE")).evidence().evidenceId();case "MEDIA"->new MediaEvidenceStore(ds,clock,roadmaps).record(space,roadmap,actor,key(),new MediaEvidenceStore.Input(node,source,2,"Memo"),trace,()->new MediaReferenceClient.Reference(space,source,actor,2,"Pinned file.pdf","application/pdf",42,"a".repeat(64),"AVAILABLE","PRIVATE")).evidence().evidenceId();default->throw new IllegalArgumentException();};}
 LearningStudyStore.Session session(UUID node){return study.record(space,roadmap,actor,key(),new LearningStudyStore.Input(node,clock.instant().minusSeconds(3600).toString(),clock.instant().minusSeconds(1800).toString(),"Original session"),trace).session();}
 EvidenceSessionStore.Link link(UUID evidence,String kind,LearningStudyStore.Session session,long expected){return links.change(space,roadmap,evidence,kind,actor,expected,new EvidenceSessionStore.Input(session.sessionId(),session.version()),trace);}
 int events(UUID link){return sql.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregatetype='evidence-session' AND aggregateid=?",Integer.class,link);}
}
